int hidp_ioctl(struct socket *sock, unsigned int cmd, void __user *argp)
{
    int ret = -EINVAL;
    struct hidp_connadd add;
    struct hidp_conndel del;
    struct hidp_connlist connlist;
    struct hidp_conninfo conninfo;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    switch (cmd) {
    case HIDP_ADD_CONNECTION:
        if (copy_from_user(&add, argp, sizeof(add)))
            return -EFAULT;
        ret = hidp_add_connection(sock, &add);
        break;
    case HIDP_DEL_CONNECTION:
        if (copy_from_user(&del, argp, sizeof(del)))
            return -EFAULT;
        ret = hidp_del_connection(sock, &del);
        break;
    case HIDP_GET_CONNLIST:
        if (copy_from_user(&connlist, argp, sizeof(connlist)))
            return -EFAULT;
        ret = hidp_get_connlist(sock, &connlist);
        break;
    case HIDP_GET_CONNINFO:
        if (copy_from_user(&conninfo, argp, sizeof(conninfo)))
            return -EFAULT;
        ret = hidp_get_conninfo(sock, &conninfo);
        if (copy_to_user(argp, &conninfo, sizeof(conninfo)))
            return -EFAULT;
        break;
    default:
        break;
    }

    return ret;
}

int hidp_ioctl(struct socket *sock, unsigned int cmd, void __user *argp)
{
    int ret = -EFAULT;
    struct hidp_conn_add_req add_req;
    struct hidp_conn_info conn_info;
    struct hidp_conn_list conn_list;
    struct sock *sk = sock->sk;
    struct hidp_info *hidp;
    int need_put = 0;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    switch (cmd) {
    case HIDP_CTL_ADD:
        if (copy_from_user(&add_req, argp, sizeof(add_req)))
            break;
        hidp = hidp_add_connection(&add_req);
        if (IS_ERR(hidp)) {
            ret = PTR_ERR(hidp);
            break;
        }
        need_put = 1;
        ret = 0;
        break;
    case HIDP_CTL_DEL:
        if (copy_from_user(&conn_info, argp, sizeof(conn_info)))
            break;
        hidp_del_connection(&conn_info);
        ret = 0;
        break;
    case HIDP_CTL_GETCONNLIST:
        if (copy_from_user(&conn_list, argp, sizeof(conn_list)))
            break;
        ret = hidp_get_conn_list(sock, &conn_list);
        break;
    case HIDP_CTL_GETCONNINFO:
        if (copy_from_user(&conn_info, argp, sizeof(conn_info)))
            break;
        ret = hidp_get_conn_info(sock, &conn_info);
        if (!ret)
            if (copy_to_user(argp, &conn_info, sizeof(conn_info)))
                ret = -EFAULT;
        break;
    default:
        ret = -EINVAL;
        break;
    }

    if (need_put)
        sock_put(sk);

    return ret;
}

int hidp_ioctl(struct socket *sock, unsigned int cmd, void __user *argp)
{
    int ret = 0;
    struct hidp_connadd conn_add;
    struct hidp_conndel conn_del;
    struct hidp_connlist conn_list;
    struct hidp_conninfo conn_info;
    struct hidp_connection *conn;

    switch (cmd) {
    case HIDPADDCONN:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (copy_from_user(&conn_add, argp, sizeof(conn_add)))
            return -EFAULT;

        conn = hidp_alloc_connection();
        if (!conn)
            return -ENOMEM;

        ret = hidp_connect(conn, &conn_add);
        if (ret < 0) {
            hidp_free_connection(conn);
            return ret;
        }

        sock->sk->sk_data = conn;
        return 0;

    case HIDPDELCONN:
        if (!capable(CAP_NET_ADMIN))
            return -EPERM;

        if (copy_from_user(&conn_del, argp, sizeof(conn_del)))
            return -EFAULT;

        conn = (struct hidp_connection *)sock->sk->sk_data;
        if (!conn)
            return -ENODEV;

        hidp_disconnect(conn);
        hidp_free_connection(conn);
        sock->sk->sk_data = NULL;
        return 0;

    case HIDPGETCONNLIST:
        if (copy_from_user(&conn_list, argp, sizeof(conn_list)))
            return -EFAULT;

        conn = (struct hidp_connection *)sock->sk->sk_data;
        if (!conn)
            return -ENODEV;

        if (copy_to_user(conn_list.conn_info, &conn->info, sizeof(conn->info)))
            return -EFAULT;

        return 0;

    case HIDPGETCONNINFO:
        if (copy_from_user(&conn_info, argp, sizeof(conn_info)))
            return -EFAULT;

        conn = (struct hidp_connection *)sock->sk->sk_data;
        if (!conn)
            return -ENODEV;

        if (copy_to_user(argp, &conn->info, sizeof(conn->info)))
            return -EFAULT;

        return 0;

    default:
        return -EINVAL;
    }

    return ret;
}

